mapper.select:
select

pro.P_Approve_Budget as pApproveBudget,
c1.C_Name as cName,
c1.C_Abbreviation as cAbbName,
dep.D_Name as dName,
mn.*
from Fund_Plan mn

left join SYS_Company c1 on mn.C_Id=c1.C_Id
left join SYS_Department dep on mn.D_Id=dep.D_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.State=#{params.state}


    and mn.Fp_Year=#{params.fpYear}


    and mn.P_Id=#{params.pId}


    and mn.Fp_Month=#{params.fpMonth}


    and mn.Fp_Type=#{params.fpType}


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and likeCname(#{params.cName},c1.C_Id)=true
        
    
    
        
            and INSTR(pro.P_Name,#{params.pName})
        
        
            and INSTR(c1.C_Name,#{params.cName})
        
    


    and INSTR(mn.Create_Uname,#{params.createUname})


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc

select mn.Fpd_Demand_Final
from Fund_Plan_Dtl mn
         left join Fund_Plan fp on fp.id = mn.Fp_Id
where mn.Fp_Id = #{id}
  and mn.Con_Id = #{conId}
limit 1
